// Agente ZOMBIE 🧟 v1 — SOLO el documento del bicho. El motor está en la librería.
//
// Reparto de responsabilidades (§0: app.js NO se toca para hacer un agente):
//  · app.js (framework) ..... nada suyo. No sabe qué es un zombie; solo que hay piezas `efimera`
//                             que no entran en mundo.json.
//  · mundo-autoarranque ..... `game.esqueletos` (v1.19+): estampa las piezas, compone la matriz de
//                             cada una y persigue con la MISMA pasoSeguir que usa `seguir`.
//  · este snippet ........... el DOCUMENTO: qué piezas, dónde van, cómo articulan. Ni una línea de
//                             motor, ni un `if` sobre zombies en la librería. Este mismo objeto es
//                             el que la fase 2 guardará tal cual en data/agentes/zombie.json.
//
// Qué hace: parado en su sitio hasta que te acercas a 14 bloques. Entonces gira hacia ti, te
// persigue en línea recta, mueve las piernas en oposición, la cabeza te sigue con la mirada y los
// brazos se levantan al frente (base 85°) — y vuelven a caer (reposo 0°) en cuanto te alejas.
//
// ⚠️ Es EFÍMERO a propósito: no entra en mundo.json y desaparece al recargar la pestaña.
// ⚠️ Los brazos NO tienen colisión (el rig gira y los envoltorios de colisión solo trasladan):
//    el zombie choca por su torso. Tampoco te hace daño ni te empuja: persigue, nada más.

if (typeof mc === 'undefined' || !mc.grid || !mc.pos) {
  console.warn('agente-zombie: esto solo va en la pestaña del Mundo (modo Mundo abierto).');
  return;
}
if (typeof game === 'undefined' || !game.esqueletos || !game.esqueletos.crear) {
  console.warn('agente-zombie: falta el motor de esqueletos. Ejecuta antes el snippet '
    + '«mundo-autoarranque» (v1.19 o más).');
  return;
}

// ── Las medidas ───────────────────────────────────────────────────────────────────────────────
// Todo en BLOQUES y medido desde la esquina baja del TORSO, que es la raíz. Un voxel = 1/16.
//
//   pieza    voxels      bloques              dónde queda
//   torso    12× 8×14    0,75 × 0,5  × 0,875  la raíz: 0,0,0
//   cabeza   15×15×15    0,9375 cúbica        centrada sobre el torso, apoyada en su tapa (0,875)
//   brazo     5× 5×14    0,3125× 0,3125×0,875 pegado a cada costado, hombro arriba del todo
//   pierna    5× 5×12    0,3125× 0,3125×0,75  colgando del suelo del torso (-0,75)
//
// Alto total: 0,75 (piernas) + 0,875 (torso) + 0,9375 (cabeza) = 2,5625 bloques, contra los 1,8
// del jugador. Te saca la cabeza, que es lo que se le pide a un bicho que da miedo.
//
// Ejes del mundo: [x, alto, z]. La z NEGATIVA es hacia DELANTE, a donde mira el agente, así que
// -x es su izquierda. Y en `articula`, POSITIVO es hacia delante: 0 = colgando, 90 = horizontal
// apuntándote.
const CENTRO_X = 0.375;          // (12/16)/2 — el eje del torso, del que cuelga todo lo simétrico
const PROF     = 0.09375;        // (0,5 - 0,3125)/2 — centra en profundidad una pieza de 5 voxels

const ZOMBIE = {
  nombre: 'zombie',
  raiz: { nombre: 'torso', pieza: 'asset:assets/torso-zombie.vox.json', rot: 0 },
  piezas: [
    // La cabeza no articula: MIRA. Los ±70° son el tope del cuello — pasado eso el zombie se
    // giraría entero, que es justo lo que hace el cuerpo un instante después.
    { nombre: 'cabeza', pieza: 'asset:assets/cabeza-zombie.vox.json',
      en: [CENTRO_X - 0.9375 / 2, 0.875, (0.5 - 0.9375) / 2],
      mirar: { limites: { y: [-70, 70] }, alcance: 12 } },

    // Los brazos: levantados al perseguir (85°, casi horizontal) y caídos parado (0°). El vaivén
    // es pequeño porque un zombie con los brazos en alto los lleva rígidos, no braceando.
    // El pivote nº1 del brazo es el hombro del costado izquierdo y el nº2 el del derecho.
    { nombre: 'brazo izq', pieza: 'asset:assets/brazo-zombie.vox.json',
      en: [-0.3125, 0, PROF],
      articula: { pivote: 1, base: 85, reposo: 0, amplitud: 10, fase: 180 } },
    { nombre: 'brazo der', pieza: 'asset:assets/brazo-zombie.vox.json',
      en: [0.75, 0, PROF],
      articula: { pivote: 2, base: 85, reposo: 0, amplitud: 10, fase: 0 } },

    // Las piernas: en oposición entre ellas (0 y 180) y cada brazo en oposición a SU pierna, que
    // es como anda cualquier bípedo. Sin `base`: de pie están rectas, como se dibujaron.
    { nombre: 'pierna izq', pieza: 'asset:assets/pierna-zombie.vox.json',
      en: [CENTRO_X - 0.3125, -0.75, PROF],
      articula: { pivote: 1, base: 0, reposo: 0, amplitud: 35, fase: 0 } },
    { nombre: 'pierna der', pieza: 'asset:assets/pierna-zombie.vox.json',
      en: [CENTRO_X, -0.75, PROF],
      articula: { pivote: 2, base: 0, reposo: 0, amplitud: 35, fase: 180 } }
  ],

  // Lo mismo que `seguir` de game.bloques: te ve a 14, se para a 1,2 y anda a 2,2 bloques/s (el
  // jugador va a ~4,3: te alcanza si te paras, pero no si corres).
  seguir: { deteccion: 14, distancia: 1.2, velocidad: 2.2 },

  // La caja con la que CHOCA. Con los brazos en alto mide 1,375 de ancho y no cabría por una
  // puerta de 1: choca por el torso (0,8) y los brazos atraviesan los marcos. Es el trato.
  cuerpo: { ancho: 0.8, alto: 2.5625 },

  // Ciclos de pierna por bloque recorrido. La fase avanza con la DISTANCIA, no con el reloj: si
  // se queda trabado contra una pared, las piernas se paran solas.
  andar: { cadencia: 0.7, suavidad: 0.12 }
};

// ── Plantarlo ─────────────────────────────────────────────────────────────────────────────────
// Reejecutar el snippet no debe dejar zombies acumulados por el mapa: se retiran los suyos (por
// nombre) y NO los demás agentes, que pueden ser de otro snippet.
const previos = (game.esqueletos._vivos || []).slice()
  .filter(r => r && !r.quitado && r.nombre === ZOMBIE.nombre);
previos.forEach(r => game.esqueletos.quitar(r));
if (previos.length) console.log('agente-zombie: retirado(s) ' + previos.length + ' zombie(s) anterior(es).');

// Unos pasos por delante de ti, mirando tú hacia donde mires (misma cuenta que usa app.js para el
// frente de la cámara). A 5 bloques: dentro de su detección de 14, pero sin aparecerte encima.
const p = mc.pos, fx = -Math.sin(mc.yaw), fz = -Math.cos(mc.yaw);
let x = Math.round(p[0] + fx * 5), z = Math.round(p[2] + fz * 5);
// ⚠️ mcSurfaceY solo ve la rejilla (terreno y assets macizos de 16³): si ahí hay una escalera o
// cualquier estructura fina, el zombie aparece a su altura y no encima. Cae por su peso al andar.
let sy = mcSurfaceY(x, z);
if (sy < 0) {                      // fuera del mapa o columna vacía: al pie del jugador
  x = Math.round(p[0]); z = Math.round(p[2]);
  sy = mcSurfaceY(x, z);
}
if (sy < 0) { console.warn('agente-zombie: no encuentro suelo donde plantarlo.'); return; }

const zombie = await game.esqueletos.crear(ZOMBIE, x, sy + 1, z);
if (!zombie) return;               // crear() ya ha dicho por consola qué le faltaba

console.log('🧟 zombie #' + zombie.id + ' en ' + x + ',' + (sy + 1) + ',' + z
  + ' — quieto hasta que te pongas a 14 bloques.');
console.log('   game.esqueletos.lista()   ·   game.esqueletos.quitar(' + zombie.id + ')');
